// 3D Earth Globe Coordinates & Classification (Continents, Wireframes, Telemetry Arcs)
(function(){
  function b64ToF32(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Float32Array(bytes.buffer);
  }
  function b64ToU8(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }
  window.GLOBE_DATA = {
    coords: b64ToF32(""),
    types: b64ToU8("")
  };
})();
